package com.civitas.app;

import android.app.Activity;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import org.json.JSONObject;

public class MainActivity extends Activity {
    private final int ink=Color.rgb(24,39,34),green=Color.rgb(24,105,76),muted=Color.rgb(105,120,113),paper=Color.rgb(247,248,245);
    private ApiClient api; private LinearLayout root; private EditText emailInput,passwordInput,nameInput,codeInput,tenantNameInput,tenantSlugInput,tenantIdInput,positionInput,statementInput; private String pendingEmail="";
    @Override public void onCreate(Bundle state){super.onCreate(state);api=new ApiClient(this);if(getSharedPreferences("civitas",MODE_PRIVATE).getString("token",null)!=null)home();else login();}
    private void base(String eyebrow,String title,String subtitle){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(26),dp(30),dp(26),dp(24));root.setBackgroundColor(paper);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);TextView brand=label("CIVITAS  /  COMMUNITY ELECTIONS",12,green,true);root.addView(brand);TextView heading=label(title,30,ink,true);LinearLayout.LayoutParams hp=params(-1,-2);hp.topMargin=dp(34);root.addView(heading,hp);TextView desc=label(subtitle,15,muted,false);LinearLayout.LayoutParams sp=params(-1,-2);sp.topMargin=dp(8);root.addView(desc,sp);}
    private void login(){base("","Welcome back","Sign in to participate in your community.");emailInput=field("Email address",false);passwordInput=field("Password",true);button("Sign in",()->{JSONObject body=json("email",value(emailInput),"password",value(passwordInput));api.post("/auth/login",body,(r,e)->{if(e!=null)toast(e.getMessage());else{saveToken(r);home();}});});link("Create an account",()->register());}
    private void register(){base("","Join CIVITAS","Create an account to take part in local decisions.");nameInput=field("Full name",false);emailInput=field("Email address",false);passwordInput=field("Password (8+ characters)",true);button("Create account",()->{pendingEmail=value(emailInput).trim();api.post("/auth/register",json("fullName",value(nameInput),"email",pendingEmail,"password",value(passwordInput)),(r,e)->{if(e!=null)toast(e.getMessage());else{String otp=r.optString("developmentOtp");verify(otp.isEmpty()?"":otp);}});});link("Already have an account? Sign in",()->login());}
    private void verify(String suggested){base("","Verify your email","Enter the six digit code sent to "+pendingEmail+".");codeInput=field("6 digit verification code",false);if(!suggested.isEmpty())codeInput.setText(suggested);button("Verify email",()->api.post("/auth/verify-email",json("email",pendingEmail,"code",value(codeInput)),(r,e)->{if(e!=null)toast(e.getMessage());else{saveToken(r);home();}}));link("Resend code",()->api.post("/auth/resend-otp",json("email",pendingEmail),(r,e)->{if(e!=null)toast(e.getMessage());else{String otp=r.optString("developmentOtp");if(!otp.isEmpty())codeInput.setText(otp);toast("New code sent");}}));}
    private void home(){base("","Your community","Signed in. Your account is ready for community participation.");TextView details=label("Create a society or use a tenant ID shared by your community administrator.",15,muted,false);root.addView(details);tenantIdInput=field("Society tenant ID",false);tenantIdInput.setText(getPreferences(MODE_PRIVATE).getString("tenantId",""));positionInput=field("Candidate position",false);statementInput=field("Candidate statement (20+ characters)",false);button("Submit candidate registration",()->api.post("/candidates/register",json("tenantId",value(tenantIdInput),"contestingPost",value(positionInput),"statement",value(statementInput),"phone",""),(r,e)->{if(e!=null)toast(e.getMessage());else toast("Candidate registration submitted for review");}));link("Refresh my candidate applications",()->api.get("/candidates/mine",(r,e)->toast(e==null?r.toString():e.getMessage())));link("Create a society tenant",()->createTenant());link("Sign out",()->{getSharedPreferences("civitas",MODE_PRIVATE).edit().remove("token").apply();api.post("/auth/logout",new JSONObject(),(r,e)->{});login();});}
    private void createTenant(){base("","Create a society","Start a tenant space for your community.");tenantNameInput=field("Society name",false);tenantSlugInput=field("Unique code, such as GREENMEADOWS",false);EditText city=field("City",false);button("Create society",()->api.post("/tenants",json("name",value(tenantNameInput),"code",value(tenantSlugInput),"city",value(city)),(r,e)->{if(e!=null)toast(e.getMessage());else{getPreferences(MODE_PRIVATE).edit().putString("tenantId",r.optString("id")).apply();home();toast("Society created. You can submit your candidate registration.");}}));link("Back",()->home());}
    private EditText field(String hint,boolean secret){EditText input=new EditText(this);input.setSingleLine(!hint.startsWith("Candidate statement"));input.setHint(hint);input.setTextSize(15);input.setTextColor(ink);input.setHintTextColor(muted);input.setPadding(dp(15),dp(12),dp(15),dp(12));input.setBackground(shape(Color.WHITE,Color.rgb(223,229,223),dp(12)));if(secret)input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);else if(hint.startsWith("Email"))input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);else if(hint.startsWith("6 digit"))input.setInputType(InputType.TYPE_CLASS_NUMBER);LinearLayout.LayoutParams p=params(-1,-2);p.topMargin=dp(12);root.addView(input,p);return input;}
    private void button(String text,Runnable action){Button b=new Button(this);b.setText(text);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setTextSize(15);b.setTypeface(null,Typeface.BOLD);b.setBackground(shape(green,green,dp(13)));LinearLayout.LayoutParams p=params(-1,dp(54));p.topMargin=dp(22);root.addView(b,p);b.setOnClickListener(v->action.run());}
    private void link(String text,Runnable action){TextView view=label(text,14,green,true);view.setGravity(Gravity.CENTER);LinearLayout.LayoutParams p=params(-1,dp(48));p.topMargin=dp(8);root.addView(view,p);view.setOnClickListener(v->action.run());}
    private TextView label(String text,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(text);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    private GradientDrawable shape(int color,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);d.setStroke(dp(1),stroke);return d;}
    private LinearLayout.LayoutParams params(int w,int h){return new LinearLayout.LayoutParams(w,h);}private int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}private String value(EditText e){return e.getText().toString().trim();}private JSONObject json(String... values){JSONObject j=new JSONObject();try{for(int i=0;i<values.length;i+=2)j.put(values[i],values[i+1]);}catch(Exception ignored){}return j;}private void saveToken(JSONObject response){getSharedPreferences("civitas",MODE_PRIVATE).edit().putString("token",response.optString("token")).apply();}private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
}
